import React, { useState } from 'react';
import './Login.css';

const Login = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Placeholder for login logic
    console.log('Login attempt:', formData);
  };

  return (
    <div className="login-container">
      <div className="login-content">
        {/* Logo Section */}
        <div className="logo-section">
          <div className="logo">
            <div className="logo-icon">
              <svg width="40" height="40" viewBox="0 0 40 40" fill="none">
                <path 
                  d="M20 4L24 12H32L26 18L28 26L20 22L12 26L14 18L8 12H16L20 4Z" 
                  fill="var(--indigo-dye)"
                />
              </svg>
            </div>
            <span className="logo-text">HCEN</span>
          </div>
        </div>

        {/* Login Form Card */}
        <div className="login-card">
          <h1 className="login-title">Iniciar Sesión en HCEN</h1>

          <form onSubmit={handleSubmit} className="login-form">
            <div className="form-group">
              <label htmlFor="username" className="form-label">Usuario</label>
              <input
                type="text"
                id="username"
                name="username"
                value={formData.username}
                onChange={handleInputChange}
                className="form-input"
                placeholder="Ingrese su nombre de usuario"
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="password" className="form-label">Contraseña</label>
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleInputChange}
                className="form-input"
                placeholder="Ingrese su contraseña"
                required
              />
            </div>

            <button type="submit" className="login-button">
              Iniciar Sesión
            </button>
          </form>

          <div className="forgot-password">
            <a href="#" className="forgot-link">Olvidé mi Contraseña</a>
          </div>
        </div>

        {/* Footer */}
        <div className="footer">
          <div className="footer-separator"></div>
          <p className="copyright">© 2024 HCEN. Todos los derechos reservados.</p>
        </div>
      </div>
    </div>
  );
};

export default Login;
